/* ---- generic repeatable two-field row group (name + description) ---- */
function makeRowGroup(listId, addBtnId, nameEn, namePh, descEn, descPh, namePhTh, descPhTh){
  var list=g(listId);
  function addRow(nameVal,descVal){
    var row=document.createElement('div');
    row.className='se-rrow';
    row.innerHTML='<input class="se-input rr-name" type="text" placeholder="'+(L==='th'?namePhTh:namePh)+'" value="'+(nameVal||'').replace(/"/g,'&quot;')+'">'+
      '<textarea class="se-textarea rr-desc" placeholder="'+(L==='th'?descPhTh:descPh)+'">'+(descVal||'')+'</textarea>'+
      '<div class="se-rdel">&times;</div>';
    row.querySelector('.se-rdel').addEventListener('click',function(){row.remove()});
    list.appendChild(row);
  }
  g(addBtnId).addEventListener('click',function(){addRow('','')});
  return {addRow:addRow, list:list};
}
