/* ---- trait chips ---- */
var traits=[];
function renderTraits(){
  g('se-trait-chips').innerHTML=traits.map(function(t,i){
    return '<span class="se-chip">'+t+'<b data-i="'+i+'">&times;</b></span>';
  }).join('');
  qa('#se-trait-chips b').forEach(function(b){
    b.addEventListener('click',function(){traits.splice(parseInt(b.getAttribute('data-i')),1);renderTraits();});
  });
}
function addTrait(){
  var v=g('f-trait-input').value.trim();
  if(v){traits.push(v);g('f-trait-input').value='';renderTraits();}
}
