/* TABS */
qa('.setab').forEach(function(t){
  t.addEventListener('click',function(){go(t.getAttribute('data-t'))});
});
function go(target){
  curIdx=TABS.indexOf(target);
  qa('.setab').forEach(function(x){x.classList.toggle('on',x.getAttribute('data-t')===target)});
  qa('.sepanel').forEach(function(p){p.classList.toggle('on',p.getAttribute('data-p')===target)});
  g('se-back').toggleAttribute('disabled',curIdx===0);
  g('se-next').textContent=(curIdx===TABS.length-1)?(L==='th'?'ยืนยันการสมัคร':'Submit Enlistment'):(L==='th'?'ถัดไป':'Next');
}
g('se-back').addEventListener('click',function(){if(curIdx>0)go(TABS[curIdx-1])});
g('se-next').addEventListener('click',function(){
  if(curIdx<TABS.length-1){go(TABS[curIdx+1])}
  else{submit()}
});

function toast(msg){
  var el=g('se-toast');el.textContent=msg;el.classList.add('show');
  setTimeout(function(){el.classList.remove('show')},2600);
}

function setLang(lang){
  L=lang;
  document.documentElement.setAttribute('lang-mode',lang);
  qa('#lg-en,#lg-th').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-l')===lang)});
  qa('[data-en]').forEach(function(el){
    var v=lang==='th'?el.getAttribute('data-th'):el.getAttribute('data-en');
    if(v!=null)el.innerHTML=v;
  });
  qa('[data-pen]').forEach(function(el){
    var v=lang==='th'?el.getAttribute('data-pth'):el.getAttribute('data-pen');
    if(v!=null)el.setAttribute('placeholder',v);
  });
  go(TABS[curIdx]);
}
g('lg-en').addEventListener('click',function(){setLang('en')});
g('lg-th').addEventListener('click',function(){setLang('th')});

function sendToST(text){
  try{
    var doc=(window.parent&&window.parent.document)?window.parent.document:document;
    var ta=doc.querySelector('#send_textarea')||doc.querySelector('textarea');
    if(ta){
      var setter=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set;
      setter.call(ta,text);
      ta.dispatchEvent(new Event('input',{bubbles:true}));
      setTimeout(function(){
        var btn=doc.querySelector('#send_but');
        if(btn){btn.click();}
        else{
          ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',keyCode:13,which:13,bubbles:true}));
        }
      },120);
      return true;
    }
  }catch(e){}
  try{navigator.clipboard.writeText(text)}catch(e2){}
  return false;
}

function readRows(listEl){
  return qa('.se-rrow',listEl).map(function(row){
    return {name:row.querySelector('.rr-name').value.trim(),description:row.querySelector('.rr-desc').value.trim()};
  }).filter(function(x){return x.name||x.description});
}
function readExtraRows(){
  return qa('.se-rrow',extraList).map(function(row){
    return {label:row.querySelector('.rr-label').value.trim(),value:row.querySelector('.rr-value').value.trim()};
  }).filter(function(x){return x.label||x.value});
}

function submit(){
  var name=g('f-name').value.trim();
  if(!name){toast(L==='th'?'กรุณากรอกชื่อจริง':'Please enter a true name');go('t1');return;}

  var codename,codenameGlyph;
  if(desigType==='greek'){
    if(!selectedGreek){toast(L==='th'?'กรุณาเลือกนามรหัส':'Please select a codename designation');go('t2');return;}
    codename=selectedGreek[1];
    codenameGlyph=selectedGreek[0];
  }else{
    var num=g('f-numeric').value.trim();
    if(!num){toast(L==='th'?'กรุณาระบุหมายเลข':'Please enter a numeric designation');go('t2');return;}
    codename=num;
    codenameGlyph=num;
  }

  var data={
    charColor:selectedColor,
    name:name,
    age:g('f-age').value.trim(),
    persona:g('f-persona').value.trim(),
    appearance:g('f-appearance').value.trim(),
    race:selectedRace?selectedRace[0]:'',
    clan:(selectedRace&&selectedRace[0]==='Beastkin')?g('f-clan').value.trim():'',
    designationType:desigType,
    codename:codename,
    codenameGlyph:codenameGlyph,
    specialty:selectedSpecialty?selectedSpecialty[0]:'',
    abilities:readRows(abilityGroup.list),
    gear:readRows(gearGroup.list),
    traits:traits.slice(),
    recruitment:g('f-recruitment').value.trim(),
    legend:g('f-legend').value.trim(),
    motive:g('f-motive').value.trim(),
    extra:readExtraRows()
  };
  var txt='<SHADOW_DOSSIER>\n'+JSON.stringify(data)+'\n</SHADOW_DOSSIER>';
  var ok=sendToST(txt);
  toast(ok?(L==='th'?'ส่งใบสมัครแล้ว...':'Enlistment submitted...'):(L==='th'?'คัดลอกไปยังคลิปบอร์ดแล้ว':'Copied to clipboard'));
}
})();
</script>
